begin;
create extension if not exists pgtap with schema extensions;
select plan(9);
insert into auth.users(id,email) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a@test.invalid'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','b@test.invalid');
insert into public.saved_items(id,user_id,status) values ('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','confirmed'),('22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','confirmed');
insert into public.places(id,saved_item_id,name,address,lat,lng,category,confidence) values ('33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111','Cafe A','Area',1,2,'cafe',.9),('44444444-4444-4444-8444-444444444444','22222222-2222-4222-8222-222222222222','Cafe B','Area',1,2,'cafe',.9);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);
select throws_ok($$select public.record_reminder('55555555-5555-4555-8555-555555555555','44444444-4444-4444-8444-444444444444',now(),'navigate',now())$$,'42501',null,'A cannot log B reminder');
select is(public.record_reminder('55555555-5555-4555-8555-555555555555','33333333-3333-4333-8333-333333333333',now(),'ignored',null),'ignored','sent row starts ignored');
select is(public.record_reminder('55555555-5555-4555-8555-555555555555','33333333-3333-4333-8333-333333333333',now(),'navigate',now()),'navigate','navigation updates the row');
select is(public.record_reminder('55555555-5555-4555-8555-555555555555','33333333-3333-4333-8333-333333333333',now(),'snooze',now()),'navigate','duplicate delivery preserves first action');
select is((select count(*)::integer from public.reminders),1,'retry does not duplicate');
select throws_ok($$update public.reminders set action='snooze'$$,'42501',null,'direct action writes require RPC');
select throws_ok($$select public.refresh_place_coordinates('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','33333333-3333-4333-8333-333333333333',3,4)$$,'42501',null,'client cannot refresh privileged coordinates');
select is(public.record_reminder('66666666-6666-4666-8666-666666666666','33333333-3333-4333-8333-333333333333',now(),'been_there',now()),'been_there','visit interaction recorded');
select is((select status from public.saved_items where id='11111111-1111-4111-8111-111111111111'),'visited','visit status and reminder action are atomic');
select * from finish();
rollback;
